import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Server, Snapshot } from '../types'
import type { Declared } from './parse'
import {
  PORT_FILES,
  declaredPorts,
  describeJs,
  parseArgs,
  parseContainers,
  parseCwds,
  groupByCheckout,
  parseListeners,
} from './parse'

const PANE = 'running-servers'
const TITLE = 'Servers'
const REFRESH_MS = 5000
const snapshot = atom({ plugin: 'running-servers', key: 'snapshot' } as const, {
  servers: [],
  at: 0,
} as Snapshot)
// The row (pid:port) whose Kill was pressed once and waits for Confirm.
const armed = atom({ plugin: 'running-servers', key: 'armed' } as const, null as string | null)
const showAll = atom({ plugin: 'running-servers', key: 'showAll' } as const, false)

// Directory → the git common dir of the checkout it sits in and that checkout's
// root ('' when none). Every worktree of one repository shares a common dir, so
// it names the project; the root names the worktree.
type Checkout = { repo: string; top: string }
const repoOf = new Map<string, Promise<Checkout>>()
let projectRepo = ''
let projectTop = ''
let home = ''
// Port → what the project's own files say listens there; read at start and on Refresh.
let declared = new Map<number, Declared>()

function shorten(path: string) {
  return home && path.startsWith(home) ? `~${path.slice(home.length)}` : path
}

function rowKey(s: Server) {
  return `${s.pid}:${s.port}`
}

function lookupRepo($: EngineInterface, dir: string): Promise<Checkout> {
  let known = repoOf.get(dir)
  if (!known) {
    known = $.process
      .run(['git', '-C', dir, 'rev-parse', '--path-format=absolute', '--git-common-dir', '--show-toplevel'])
      .then(r => {
        const [repo = '', top = ''] = r.exitCode === 0 ? r.stdout.trim().split('\n') : []
        return { repo, top }
      })
      .catch(() => ({ repo: '', top: '' }))
    repoOf.set(dir, known)
  }
  return known
}

async function findProject($: EngineInterface) {
  const who = await $.process.run(['sh', '-c', 'echo $HOME']).catch(() => undefined)
  home = who?.stdout.trim() ?? ''
  const here = await $.process.run(['pwd']).catch(() => undefined)
  const mine = here ? await lookupRepo($, here.stdout.trim()) : { repo: '', top: '' }
  projectRepo = mine.repo
  projectTop = mine.top
  await scanProject($)
}

// Reads every tracked file that can declare a port (compose files, package.json
// scripts, framework configs, .env files, justfile, Makefile, Procfile).
async function scanProject($: EngineInterface) {
  if (!projectTop) return
  const files = await $.process
    .run(['git', 'ls-files'], { cwd: projectTop })
    .then(r => r.stdout.split('\n').filter(f => PORT_FILES.test(f)).slice(0, 200))
    .catch(() => [] as string[])
  const next = new Map<number, Declared>()
  for (const file of files) {
    const text = await $.fs.read(`${projectTop}/${file}`).catch(() => '')
    for (const d of declaredPorts(file, typeof text === 'string' ? text : '')) {
      // A bare PORT says less than api_port or a compose service, so those replace it.
      const known = next.get(d.port)
      if (!known || (/^port$/i.test(known.name) && !/^port$/i.test(d.name))) next.set(d.port, d)
    }
  }
  declared = next
}

async function rescan($: EngineInterface) {
  await scanProject($)
  await refresh($)
}

async function refresh($: EngineInterface) {
  try {
    const listen = await $.process.run(
      ['lsof', '-w', '-nP', '-iTCP', '-sTCP:LISTEN', '-F', 'pcLn'],
      { timeoutMs: 10000 },
    )
    const servers = parseListeners(listen.stdout)
    if (servers.length > 0) {
      const pids = [...new Set(servers.map(s => s.pid))].join(',')
      const cwd = await $.process.run(['lsof', '-w', '-a', '-d', 'cwd', '-p', pids, '-F', 'pn'], {
        timeoutMs: 10000,
      })
      const cwds = parseCwds(cwd.stdout)
      const ps = await $.process.run(['ps', '-o', 'pid=,args=', '-p', pids], { timeoutMs: 10000 })
      const args = parseArgs(ps.stdout)
      for (const s of servers) {
        s.cwd = cwds.get(s.pid)
        s.tool = describeJs(s.command, args.get(s.pid) ?? '')
      }
    }
    const docker = await $.process
      .run([
        'docker', 'ps', '--format',
        '{{.Names}}\t{{.Ports}}\t{{.Label "com.docker.compose.project.working_dir"}}\t{{.Label "com.docker.compose.service"}}',
      ], { timeoutMs: 10000 })
      .catch(() => undefined)
    if (docker?.exitCode === 0) {
      for (const c of parseContainers(docker.stdout)) {
        for (const s of servers) {
          if (!c.ports.includes(s.port)) continue
          s.container = c.name
          s.cwd = c.dir
          s.tool = undefined
          if (c.service) s.role = c.service
        }
      }
    }
    for (const s of servers) {
      const d = declared.get(s.port)
      if (!d) continue
      s.role ??= d.name
      s.source = d.source
    }
    await Promise.all(
      servers.map(async s => {
        const at = s.cwd && s.cwd !== '/' ? await lookupRepo($, s.cwd) : undefined
        if (at?.top) s.checkout = at.top
        const inRepo = !!projectRepo && at?.repo === projectRepo
        s.isProject = !!projectRepo && (!!s.source || (inRepo && (!!s.container || !!s.tool)))
      }),
    )
    const project = projectRepo ? projectRepo.replace(/\/\.git$/, '').split('/').pop() : undefined
    await update($, snapshot, () => ({ servers, at: Date.now(), project, declared: declared.size }))
  } catch (err) {
    await update($, snapshot, prev => ({ ...prev, at: Date.now(), error: String(err) }))
  }
}

async function arm($: EngineInterface, key: string | null) {
  await update($, armed, () => key)
}

async function toggleAll($: EngineInterface) {
  await update($, showAll, all => !all)
}

// A process gets SIGTERM; a container port belongs to Docker's own process,
// so the container is stopped instead. A refusal shows as the error line.
async function kill($: EngineInterface, s: Server) {
  await update($, armed, () => null)
  const argv = s.container ? ['docker', 'stop', s.container] : ['kill', '-TERM', String(s.pid)]
  const ran = await $.process.run(argv, { timeoutMs: 30000 }).catch(err => ({
    exitCode: 1,
    stderr: String(err),
  }))
  await refresh($)
  if (ran.exitCode !== 0) {
    await update($, snapshot, prev => ({ ...prev, error: `${argv.join(' ')}: ${ran.stderr.trim()}` }))
  }
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'servers',
      description: "Show the servers this project runs, found from the ports its files declare",
    })
    await findProject($)
    void refresh($)
    $.clock.every(REFRESH_MS, () => void refresh($))

    return next(e)
  })

  on('command.run', { command: 'servers' }, async $ => {
    await refresh($)
    await $.ui.open({ id: PANE, title: TITLE })
    const { servers, project } = await read($, snapshot)
    const mine = servers.filter(s => s.isProject).length

    return {
      text: `Servers pane opened: ${mine} running for ${project ?? 'this project'}, ${servers.length} ports listening on the machine.`,
    }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button, Link } = $.ui.resolve(e)
    const { servers, at, error, project, declared: declaredCount } = await read($, snapshot)
    const pending = await read($, armed)
    const all = (await read($, showAll)) || !project
    const shown = all ? servers : servers.filter(s => s.isProject)
    const time = at ? new Date(at).toLocaleTimeString() : 'never'

    return (
      <Box flexDirection="column">
        <Box flexDirection="row" gap={1}>
          <Text bold>
            {all
              ? `${servers.length} listening on this machine`
              : `${shown.length} running for ${project}`}
          </Text>
          <Text dimColor>
            {declaredCount ? `${declaredCount} ports declared · ` : ''}updated {time}
          </Text>
          <Button key="refresh" label="Refresh" hotkey="r" onPress={() => rescan($)} />
          {project && (
            <Button
              key="scope"
              label={all ? `Only ${project}` : `Show all ${servers.length}`}
              hotkey="a"
              dimColor
              onPress={() => toggleAll($)}
            />
          )}
        </Box>
        {error && <Text color="red">{error}</Text>}
        {shown.length === 0 && <Text dimColor>Nothing from {project} is running.</Text>}
        {groupByCheckout(shown, projectTop).map(group => (
          <Box flexDirection="column" key={`group:${group.checkout}`}>
            <Text bold color={group.checkout === projectTop ? 'green' : undefined}>
              {group.checkout ? shorten(group.checkout) : 'Outside any checkout'}
              {group.checkout === projectTop ? ' (this session)' : ''}
            </Text>
            {group.servers.map(s => (
              <Box flexDirection="row" gap={1} key={rowKey(s)}>
                <Text color="cyan">{String(s.port).padStart(7)}</Text>
                <Text bold>{s.role ?? s.container ?? s.tool ?? s.command}</Text>
                {s.tool && <Link href={`http://localhost:${s.port}`} />}
                <Text dimColor>
                  {s.role && (s.container ?? s.tool) ? `${s.container ?? s.tool} · ` : ''}
                  {s.container ? 'container' : `pid ${s.pid}`}
                </Text>
                {pending === rowKey(s) ? (
                  <>
                    <Button
                      key={`confirm:${rowKey(s)}`}
                      label={s.container ? 'Confirm stop' : 'Confirm kill'}
                      onPress={() => kill($, s)}
                    />
                    <Button key={`cancel:${rowKey(s)}`} label="Cancel" dimColor onPress={() => arm($, null)} />
                  </>
                ) : (
                  <Button
                    key={`kill:${rowKey(s)}`}
                    label={s.container ? 'Stop' : 'Kill'}
                    dimColor
                    onPress={() => arm($, rowKey(s))}
                  />
                )}
              </Box>
            ))}
          </Box>
        ))}
      </Box>
    )
  })
}

