import type { Server } from '../types'

// Parses `lsof -nP -iTCP -sTCP:LISTEN -F pcLn` field output: one field per
// line, `p` opening a process, `c`/`L` its command and user, `n` each socket.
export function parseListeners(out: string): Server[] {
  const seen = new Map<string, Server>()
  let pid = 0
  let command = ''
  let user = ''
  for (const line of out.split('\n')) {
    const tag = line[0]
    const value = line.slice(1)
    if (tag === 'p') pid = Number(value)
    else if (tag === 'c') command = value
    else if (tag === 'L') user = value
    else if (tag === 'n') {
      const cut = value.lastIndexOf(':')
      const port = Number(value.slice(cut + 1))
      const address = value.slice(0, cut)
      const key = `${pid}:${port}`
      const known = seen.get(key)
      if (known) {
        if (!known.address.includes(address)) known.address += ` ${address}`
      } else seen.set(key, { pid, command, user, address, port })
    }
  }
  return [...seen.values()].sort((a, b) => a.port - b.port)
}

// Parses `lsof -a -d cwd -p <pids> -Fpn` into pid → working directory.
export function parseCwds(out: string): Map<number, string> {
  const cwds = new Map<number, string>()
  let pid = 0
  for (const line of out.split('\n')) {
    if (line[0] === 'p') pid = Number(line.slice(1))
    else if (line[0] === 'n') cwds.set(pid, line.slice(1))
  }
  return cwds
}

export type Container = { name: string; ports: number[]; dir?: string; service?: string }

// Parses `docker ps --format '{{.Names}}\t{{.Ports}}\t{{.Label "..working_dir"}}\t{{.Label "..service"}}'`;
// the host ports are the numbers before each `->`.
export function parseContainers(out: string): Container[] {
  return out
    .split('\n')
    .filter(line => line.trim())
    .map(line => {
      const [name = '', ports = '', dir = '', service = ''] = line.split('\t')
      const host = [...ports.matchAll(/:(\d+)->/g)].map(m => Number(m[1]))
      return { name, ports: [...new Set(host)], dir: dir || undefined, ...(service ? { service } : {}) }
    })
}

// Parses `ps -o pid=,args= -p <pids>` into pid → full command line.
export function parseArgs(out: string): Map<number, string> {
  const args = new Map<number, string>()
  for (const line of out.split('\n')) {
    const m = line.match(/^\s*(\d+)\s+(.*)$/)
    if (m) args.set(Number(m[1]), m[2]!.trim())
  }
  return args
}

const RUNTIMES = new Set(['node', 'bun', 'deno', 'npm', 'npx', 'pnpm', 'yarn', 'tsx', 'vite'])

function base(path: string) {
  return path.split('/').pop() ?? path
}

// What a JS server runs: the last package named under node_modules (vite,
// tsx; the last one, so a pnpm store path reads as the package) and the
// project's own script file given to it, else the runtime and that script.
// Undefined when the process is no JS runtime.
export function describeJs(command: string, args: string): string | undefined {
  // `node_modules/.bin/../vite/bin/vite.js` is how a .bin shim starts Vite.
  const tokens = args.split(/\s+/).map(t => t.replace(/[^/\s]+\/\.\.\//g, ''))
  const runtime = base(tokens[0] ?? '')
  if (!RUNTIMES.has(runtime) && !RUNTIMES.has(command)) return undefined
  const pkgs = [...tokens.join(' ').matchAll(/node_modules\/(?:\.bin\/)?((?:@[^/\s]+\/)?[^/\s]+)/g)]
    .map(m => m[1]!)
    .filter(p => !p.startsWith('.'))
  const pkg = pkgs[pkgs.length - 1]
  // A script file wins over a flag's value (`--import tsx/esm src/server.ts`).
  const own = tokens.slice(1).filter(t => !t.startsWith('-') && !t.includes('node_modules'))
  const script = own.find(t => /\.[cm]?[jt]sx?$/.test(t)) ?? (pkg ? undefined : own[0])
  if (pkg) return script ? `${pkg} ${base(script)}` : pkg
  return script ? `${runtime} ${base(script)}` : runtime
}

/** A port the project's own files say something listens on. */
export type Declared = { port: number; name: string; source: string }

// The files that declare ports, matched against `git ls-files` paths.
export const PORT_FILES =
  /(^|\/)((docker-)?compose[^/]*\.ya?ml|package\.json|(vite|astro|next|nuxt|svelte|webpack)\.config\.[cm]?[jt]s|\.env[^/]*|justfile|Justfile|Makefile|Procfile[^/]*|launch\.json)$/

function valid(port: number) {
  return Number.isInteger(port) && port >= 1024 && port <= 65535
}

function dirName(path: string) {
  const parts = path.split('/')
  return parts.length > 1 ? parts[parts.length - 2]! : ''
}

// Reads the ports one project file declares. Each kind of file has its own
// shape; anything unrecognised declares nothing.
export function declaredPorts(path: string, text: string): Declared[] {
  const file = base(path)
  const found: Declared[] = []
  const add = (port: number, name: string) => {
    if (valid(port) && !found.some(d => d.port === port)) found.push({ port, name, source: path })
  }

  if (/compose[^/]*\.ya?ml$/.test(file)) {
    // services:\n  <name>:\n    ports:\n      - "<host>:<container>"
    let service = ''
    let inPorts = false
    let portsIndent = 0
    for (const line of text.split('\n')) {
      const indent = line.length - line.trimStart().length
      const body = line.trim()
      if (!body || body.startsWith('#')) continue
      const key = body.match(/^([\w.-]+):\s*$/)
      if (indent === 2 && key) service = key[1]!
      if (inPorts && indent <= portsIndent && !body.startsWith('-')) inPorts = false
      if (/^ports:\s*$/.test(body)) {
        inPorts = true
        portsIndent = indent
        continue
      }
      if (inPorts && body.startsWith('-')) {
        // "${VAR:-5433}:5432", "127.0.0.1:8080:80", 8080:80, "3000"
        const spec = body.replace(/^-\s*/, '').replace(/["']/g, '').replace(/\$\{\w+:-(\d+)\}/g, '$1')
        const parts = spec.split('/')[0]!.split(':')
        add(Number(parts.length >= 2 ? parts[parts.length - 2] : parts[0]), service)
      }
    }
    return found
  }

  if (file === 'package.json') {
    let scripts: Record<string, string> = {}
    try {
      scripts = (JSON.parse(text) as { scripts?: Record<string, string> }).scripts ?? {}
    } catch {
      return found
    }
    for (const [script, line] of Object.entries(scripts)) {
      for (const m of line.matchAll(/(?:--port[= ]|\bPORT=|\s-p\s)(\d+)/g)) {
        add(Number(m[1]), `${dirName(path) || 'root'} ${script}`)
      }
    }
    return found
  }

  if (/\.config\.[cm]?[jt]s$/.test(file)) {
    for (const m of text.matchAll(/\bport\s*:\s*(\d+)/g)) add(Number(m[1]), `${dirName(path) || 'root'} ${file.split('.')[0]}`)
    return found
  }

  if (file === 'launch.json') {
    for (const m of text.matchAll(/"name"\s*:\s*"([^"]+)"[^}]*?"port"\s*:\s*(\d+)/g)) add(Number(m[2]), m[1]!)
    return found
  }

  // .env files, justfile, Makefile, Procfile: FOO_PORT=4000, api_port=$((3000 + …)),
  // ${FOO_PORT:-4000}, --port 4000
  for (const m of text.matchAll(/\b(\w*port\w*)\s*:?=\s*["']?\$?\(*\s*(\d{4,5})\b/gi)) add(Number(m[2]), m[1]!)
  for (const m of text.matchAll(/\$\{(\w*PORT\w*):-(\d{4,5})\}/g)) add(Number(m[2]), m[1]!)
  for (const m of text.matchAll(/--port[= ](\d{4,5})\b/g)) add(Number(m[1]), file)
  return found
}

export type Group<T> = { checkout: string; servers: T[] }

// Groups servers under the checkout they were started from: the session's own
// first, then the rest by path, servers outside any checkout last ('').
export function groupByCheckout<T extends { checkout?: string; port: number }>(
  servers: T[],
  first: string,
): Group<T>[] {
  const groups = new Map<string, T[]>()
  for (const s of servers) {
    const key = s.checkout ?? ''
    groups.set(key, [...(groups.get(key) ?? []), s])
  }
  const rank = (key: string) => (key === first ? 0 : key === '' ? 2 : 1)
  return [...groups.entries()]
    .sort(([a], [b]) => rank(a) - rank(b) || a.localeCompare(b))
    .map(([checkout, list]) => ({ checkout, servers: list.sort((x, y) => x.port - y.port) }))
}

