files.types/index.d.ts:
export type Server = {
  pid: number
  command: string
  user: string
  address: string
  port: number
  cwd?: string
  /** The Docker container publishing this port; its process is Docker's own. */
  container?: string
  /** What a JS runtime process runs (`vite`, `node server.ts`); absent for anything else. */
  tool?: string
  /** The root of the git checkout (worktree) cwd sits in; absent outside any. */
  checkout?: string
  /** The name the project's files give this port, and the file that declares it. */
  role?: string
  source?: string
  /** True when the project declares this port, or it is this repository's container or JS server. */
  isProject?: boolean
}

export type Snapshot = {
  servers: Server[]
  at: number
  project?: string
  /** How many ports the project's files declare. */
  declared?: number
  error?: string
}

declare module 'claude-code' {
  interface PluginState {
    'running-servers': { snapshot: Snapshot; armed: string | null; showAll: boolean }
  }
}
